def encode(message):
    result = []
    for char in message:
        if char.isalpha():
            swapped = char.swapcase()
            if swapped.lower() in 'aeiou':
                result.append(chr(ord(swapped) + 2))
            else:
                result.append(swapped)
        else:
            result.append(char)
    return ''.join(result)
